// План specs/estimates-sms-link.md 1.3 (кейс ES-03). Гость, только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { EST_0013, NOT_VALID, NOT_VALID_HINT, openPublicEstimate } from './estimate-sms-helpers';

const DEVICES = ['@desktop', '@android'] as const;

const lastChanged = EST_0013.token.slice(0, -1) + (EST_0013.token.endsWith('0') ? '1' : '0');
const VARIANTS: { name: string; token: string | null }[] = [
  { name: 'unknown token', token: '00000000-0000-0000-0000-000000000000' },
  { name: 'token with one changed character', token: lastChanged },
  { name: 'truncated token', token: EST_0013.token.slice(0, 18) },
  { name: 'empty t', token: '' },
  { name: 'no t parameter', token: null },
];

test.describe('Estimate SMS link: invalid link (#05c270)', () => {
  for (const device of DEVICES) {
    test(`Broken estimate links show "This estimate link is not valid" #05c270 ${device} @prod-safe`, async ({ page }) => {
      for (const v of VARIANTS) {
        await test.step(v.name, async () => {
          await openPublicEstimate(page, v.token);
          // Комментарий программиста п.1: Битая/неполная ссылка → «This estimate link is not valid»
          await expect(page.getByText(NOT_VALID, { exact: true })).toBeVisible();
          await expect(page.getByText(NOT_VALID_HINT)).toBeVisible();
          await expect(page.getByText(/Estimate #EST-/)).toHaveCount(0);
          await expect(page.getByRole('button', { name: 'Download PDF' })).toHaveCount(0);
        });
      }
    });
  }
});
